import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.sql.*;
public class EventRegistration extends JFrame {
 private final JTextField student=new JTextField(12), event=new JTextField(8);private final DefaultTableModel model=new DefaultTableModel(new String[]{"Student ID","Event ID","Registered At"},0);private final JTable table=new JTable(model);
 private final String url=System.getenv().getOrDefault("JDBC_URL","jdbc:mysql://localhost:3306/campus_events"),user=System.getenv().getOrDefault("JDBC_USER","root"),pass=System.getenv().getOrDefault("JDBC_PASSWORD","");
 public EventRegistration(){super("Campus Event Registration");JPanel form=new JPanel();form.add(new JLabel("Student"));form.add(student);form.add(new JLabel("Event ID"));form.add(event);JButton register=new JButton("Register"),refresh=new JButton("Refresh");form.add(register);form.add(refresh);add(form,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);JMenuBar bar=new JMenuBar();JMenu menu=new JMenu("File");JMenuItem exit=new JMenuItem("Exit");exit.addActionListener(e->dispose());menu.add(exit);bar.add(menu);setJMenuBar(bar);register.addActionListener(e->registerAsync());refresh.addActionListener(e->loadAsync());setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(650,400);}
 private Connection connect()throws SQLException{return DriverManager.getConnection(url,user,pass);}
 private void registerAsync(){String sid=student.getText().trim(),eid=event.getText().trim();if(sid.isEmpty()||eid.isEmpty()){JOptionPane.showMessageDialog(this,"Enter student and event IDs");return;}new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO registrations(student_id,event_id) VALUES(?,?)")){p.setString(1,sid);p.setLong(2,Long.parseLong(eid));p.executeUpdate();return "Registration successful";}}protected void done(){try{JOptionPane.showMessageDialog(EventRegistration.this,get());loadAsync();}catch(Exception ex){JOptionPane.showMessageDialog(EventRegistration.this,"Registration failed (possibly duplicate): "+ex.getMessage(),"Error",JOptionPane.ERROR_MESSAGE);}}}.execute();}
 private void loadAsync(){new SwingWorker<Object[][],Void>(){protected Object[][] doInBackground()throws Exception{try(Connection c=connect();PreparedStatement p=c.prepareStatement("SELECT student_id,event_id,registered_at FROM registrations ORDER BY id DESC LIMIT 100 OFFSET 0");ResultSet r=p.executeQuery()){java.util.List<Object[]> rows=new java.util.ArrayList<>();while(r.next())rows.add(new Object[]{r.getString(1),r.getLong(2),r.getTimestamp(3)});return rows.toArray(new Object[0][]);}}protected void done(){try{model.setRowCount(0);for(Object[] row:get())model.addRow(row);}catch(Exception ex){JOptionPane.showMessageDialog(EventRegistration.this,ex.getMessage());}}}.execute();}
 public static void main(String[] a){SwingUtilities.invokeLater(()->new EventRegistration().setVisible(true));}
}
